using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Text;using System.Text.RegularExpressions;using System.Web.Script.Serialization;
namespace XHLLauncher {
 public sealed class EvidenceItem {public string Source,Name,Text,Path;public DateTime WrittenUtc;}
 public sealed class IncidentBundle {public DateTime CapturedUtc;public string Trigger;public object Observations;public List<EvidenceItem> Items=new List<EvidenceItem>();public string Conclusion="Evidence collected; cause is not established by correlation alone.";}
 public static class IncidentEvidence {
  static string Redact(string text){string value=Regex.Replace(text??"","(?i)(\"(?:password|PhoneViewKey|token|secret)\"\\s*:\\s*)\"(?:\\\\.|[^\"\\\\])*\"","$1\"[redacted]\"");value=Regex.Replace(value,"(?i)((?:password|PhoneViewKey|token|secret)\\s*[:=]\\s*)(?:\"[^\"]*\"|'[^']*'|[^\\s,;]+)","$1[redacted]");return Regex.Replace(value,@"(https?://[^/\s]+/)[0-9a-fA-F]{32,}/","$1[private]/");}
  public static string Tail(string path,int limit){using(var fs=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){long start=Math.Max(0,fs.Length-limit);fs.Seek(start,SeekOrigin.Begin);using(var r=new StreamReader(fs)){if(start>0)r.ReadLine();return Redact(r.ReadToEnd());}}}
  public static IncidentBundle Capture(string app,string server,string trigger,string destination,object observations=null){var b=new IncidentBundle{CapturedUtc=DateTime.UtcNow,Trigger=trigger,Observations=observations};var cfg=ConfigReader.Read(server);var roots=new[]{Path.GetFullPath(Path.Combine(server,cfg.LogDirectory)),Path.Combine(server,"LauncherLogs"),Path.Combine(server,"XHL-Diagnostic-Logs"),Path.Combine(server,"XHL-Mods-1.0","Flight"),Path.Combine(server,"XHL-Mods-1.0","Gifting"),Path.Combine(server,"XHL-Mods-1.0","FlightStamina"),app};
   foreach(var root in roots){try{if(!Directory.Exists(root))continue;foreach(var f in new DirectoryInfo(root).GetFiles().Where(f=>f.Extension==".log"||f.Name.EndsWith("LAST-START.txt",StringComparison.OrdinalIgnoreCase)).OrderByDescending(f=>f.LastWriteTimeUtc).Take(3)){try{b.Items.Add(new EvidenceItem{Source=root==app?"Launcher":"Server / wrapper",Name=f.Name,Path=f.FullName,WrittenUtc=f.LastWriteTimeUtc,Text=Tail(f.FullName,65536)});}catch(Exception ex){b.Items.Add(new EvidenceItem{Source="Read failure",Name=f.Name,Text=ex.Message});}}}catch{}}
   try{using(var log=new EventLog("Application")){int inspected=0;for(int i=log.Entries.Count-1;i>=0&&inspected++<4000;i--){var e=log.Entries[i];if(e.TimeGenerated<DateTime.Now.AddDays(-3))break;string msg=e.Message??"";if(msg.IndexOf("enshrouded",StringComparison.OrdinalIgnoreCase)<0&&msg.IndexOf("ShroudForge",StringComparison.OrdinalIgnoreCase)<0&&msg.IndexOf("XHL",StringComparison.OrdinalIgnoreCase)<0)continue;b.Items.Add(new EvidenceItem{Source="Windows Application log",Name=e.Source+" / event "+e.InstanceId,WrittenUtc=e.TimeGenerated.ToUniversalTime(),Text=Redact(msg.Length>16384?msg.Substring(0,16384):msg)});if(b.Items.Count>35)break;}}}catch(Exception ex){b.Items.Add(new EvidenceItem{Source="Windows Application log",Name="Unavailable",Text=ex.Message});}
   if(destination!=null){Directory.CreateDirectory(destination);string file=Path.Combine(destination,"incident-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+".json");string temp=file+".pending";File.WriteAllText(temp,new JavaScriptSerializer{MaxJsonLength=4*1024*1024}.Serialize(b));File.Move(temp,file);}return b;
  }
 }
}
